[tool error]
{
  "ok": false,
  "name": "resolve_anchor",
  "error": {
    "type": "invalid_params",
    "message": "'tangent' is not one of ['station', 'pc', 'pt', 'pi', 'mc', 'pcc', 'prc', 'bearing', 'begin', 'end', 'equation', 'curve_data', 'custom']",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "alignment": {
          "type": "string",
          "minLength": 1
        },
        "anchor": {
          "type": [
            "string",
            "number",
            "object"
          ],
          "description": "BEGIN | END | PI-n | PC-n | PT-n | MC-n | T-n | EQ-n | '86+50.00' | 8650, optionally '@offset' (ft, right +, e.g. 'PC-2@18', '86+50@25L'); or {ref|station, offset, region}. BC-n and EC-n, as a Caltrans plan letters them, are PC-n and PT-n"
        },
        "kind": {
          "enum": [
            "station",
            "pc",
            "pt",
            "pi",
            "mc",
            "pcc",
            "prc",
            "bearing",
            "begin",
            "end",
            "equation",
            "curve_data",
            "custom"
          ]
        },
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-004' or 'P-201'"
        },
        "viewport": {
          "type": "string",
          "minLength": 1
        },
        "side": {
          "enum": [
            "left",
            "right",
            "above",
            "below"
          ],
          "description": "left/right of the stationing direction, or above/below on the paper (resolved to the line's left or right and recorded so); default by kind: station numbers below, bearings above, curve points and equations left, the curve bubble right"
        },
        "label_offset": {
          "type": "number"
        },
        "rotation": {
          "enum": [
            "along",
            "perpendicular",
            "horizontal"
          ]
        },
        "content": {
          "type": "string"
        },
        "sheet": {
          "type": "string",
          "minLength": 1,
          "description": "for a referenced alignment: also say where the anchor falls on that sheet (on_sheet)"
        }
      },
      "required": [
        "anchor"
      ],
      "additionalProperties": false
    },
    "example": {
      "alignment": "ALIGN-1",
      "anchor": "PC-1"
    }
  }
}

